// This file is @generated by perseid, vendored from the runtime of the CLI pack.
//! The JSON Schema of each command, for `schema` and for checking bodies before they are sent:
//! the SDK's models keep unknown fields and values, which the API would ignore. It is merged from
//! `schema.json` (`$defs`, `resources`' command words, `auth`) and each resource module's `commands`.
use std::collections::{BTreeSet, HashMap};

use serde_json::{json, Map, Value};

use super::{body::Field, error::CliError};

/// `$ref`s deeper than this stay references, their schemas under `$defs`.
const INLINE_DEPTH: usize = 6;

/// Enums longer than this are cut in error messages.
const SHOWN_VALUES: usize = 20;

/// The schema of a CLI's commands, keyed by their words (`things attachments upload`).
pub struct Schema {
    root: Value,
    /// The words of each command's key, which generated code passes.
    keys: HashMap<String, String>,
}

impl Schema {
    /// Merges the parts of the schema, each a JSON object.
    pub fn parse(parts: &[&str]) -> Result<Self, CliError> {
        let mut root = json!({"commands": {}, "$defs": {}, "resources": {}, "mcp": {}, "auth": {}});
        for part in parts {
            let part: Value = serde_json::from_str(part)
                .map_err(|error| CliError::internal(format!("schema: {error}")))?;
            for section in ["commands", "$defs", "resources", "mcp", "auth"] {
                let (Some(into), Some(from)) =
                    (root[section].as_object_mut(), part[section].as_object())
                else {
                    continue;
                };
                into.extend(from.clone());
            }
        }
        let mut commands = Map::new();
        let mut keys = HashMap::new();
        let entries = root["commands"].as_object().cloned().unwrap_or_default();
        for (key, command) in entries {
            let resource = command["resource"].as_str().unwrap_or_default();
            let words = match (
                root["resources"][resource].as_str(),
                command["command"].as_str(),
            ) {
                (Some(resource), Some(word)) => format!("{resource} {word}"),
                _ => key.clone(),
            };
            keys.insert(key, words.clone());
            commands.insert(words, command);
        }
        root["commands"] = Value::Object(commands);
        Ok(Self { root, keys })
    }

    /// What `[context.cli_mcp]` of perseid.toml says of the `mcp` server: toolsets, overrides.
    pub fn mcp(&self) -> &Value {
        &self.root["mcp"]
    }

    /// The headers of the spec's `apiKey` security schemes, lowercase: `x-api-key`, where the SDK
    /// sends the API key instead of `Authorization`.
    pub fn api_key_headers(&self) -> Vec<String> {
        (self.root["auth"]["api_key_headers"].as_array().into_iter())
            .flatten()
            .filter_map(Value::as_str)
            .map(str::to_ascii_lowercase)
            .collect()
    }

    fn commands(&self) -> impl Iterator<Item = (&String, &Value)> {
        self.root["commands"].as_object().into_iter().flatten()
    }

    fn command(&self, name: &str) -> Option<&Value> {
        self.root["commands"].get(name)
    }

    fn def(&self, reference: &str) -> Option<&Value> {
        let name = reference.strip_prefix("#/$defs/")?;
        self.root["$defs"].get(name)
    }

    /// The commands whose words start with `prefix`: `{command, method, path, summary}`.
    pub fn index(&self, prefix: &[String]) -> Vec<Value> {
        self.commands()
            .filter(|(name, _)| {
                let words: Vec<&str> = name.split(' ').collect();
                words.len() >= prefix.len() && words.iter().zip(prefix).all(|(a, b)| a == b)
            })
            .map(|(name, command)| {
                json!({
                    "command": name,
                    "method": command["method"],
                    "path": command["path"],
                    "summary": command["summary"],
                })
            })
            .collect()
    }

    /// What `schema <command>` prints: the input of the command, or with `response` its output,
    /// `$ref`s inlined.
    pub fn describe(&self, name: &str, response: bool) -> Option<Value> {
        let command = self.command(name)?;
        let mut out = Map::new();
        out.insert("command".into(), name.into());
        for key in [
            "method",
            "path",
            "summary",
            "deprecated",
            "paginated",
            "streaming",
            "output",
            "pagination",
        ] {
            if let Some(value) = command.get(key) {
                out.insert(key.into(), value.clone());
            }
        }
        let mut refs = BTreeSet::new();
        if response {
            let schema = command.get("response").cloned().unwrap_or(Value::Null);
            out.insert(
                "response".into(),
                self.inline(&schema, &mut Vec::new(), &mut refs),
            );
        } else {
            let mut properties = Map::new();
            let mut required = Vec::new();
            for param in command["params"].as_array().into_iter().flatten() {
                let arg = param["arg"].as_str().unwrap_or_default().to_owned();
                let mut schema = self.inline(&param["schema"], &mut Vec::new(), &mut refs);
                if let Value::Object(map) = &mut schema {
                    map.insert("in".into(), param["in"].clone());
                    map.insert("name".into(), param["name"].clone());
                    if let Some(description) = param.get("description") {
                        map.insert("description".into(), description.clone());
                    }
                }
                if param["required"] == true {
                    required.push(Value::String(arg.clone()));
                }
                properties.insert(arg, schema);
            }
            out.insert(
                "parameters".into(),
                json!({"type": "object", "properties": properties, "required": required}),
            );
            if let Some(body) = command.get("body") {
                let mut schema = self.inline(&body["schema"], &mut Vec::new(), &mut refs);
                if let Value::Object(map) = &mut schema {
                    map.insert("x-required".into(), body["required"].clone());
                    map.insert("x-content".into(), body["content"].clone());
                }
                out.insert("body".into(), schema);
            }
            if let Some(example) = command.get("example") {
                out.insert("example".into(), example.clone());
            }
        }
        if !refs.is_empty() {
            out.insert("$defs".into(), self.defs(refs));
        }
        Some(Value::Object(out))
    }

    /// `schema` with `$ref`s replaced by their schema, unless one is on its own path (a cycle)
    /// or too deep: those are added to `refs`.
    fn inline(
        &self,
        schema: &Value,
        stack: &mut Vec<String>,
        refs: &mut BTreeSet<String>,
    ) -> Value {
        match schema {
            Value::Object(map) => {
                if let Some(reference) = map.get("$ref").and_then(Value::as_str) {
                    let name = reference.trim_start_matches("#/$defs/").to_owned();
                    let target = self.def(reference);
                    if stack.contains(&name) || stack.len() >= INLINE_DEPTH || target.is_none() {
                        refs.insert(name);
                        return schema.clone();
                    }
                    stack.push(name);
                    let mut inlined = self.inline(target.unwrap_or(&Value::Null), stack, refs);
                    stack.pop();
                    if let Value::Object(inlined) = &mut inlined {
                        for (key, value) in map.iter().filter(|(key, _)| *key != "$ref") {
                            inlined.insert(key.clone(), value.clone());
                        }
                    }
                    return inlined;
                }
                let map = map
                    .iter()
                    .map(|(key, value)| match key.as_str() {
                        "discriminator" | "enum" | "required" => (key.clone(), value.clone()),
                        _ => (key.clone(), self.inline(value, stack, refs)),
                    })
                    .collect();
                Value::Object(map)
            }
            Value::Array(items) => Value::Array(
                items
                    .iter()
                    .map(|item| self.inline(item, stack, refs))
                    .collect(),
            ),
            other => other.clone(),
        }
    }

    /// The schemas `refs` name, and those they refer to, as they are.
    fn defs(&self, mut refs: BTreeSet<String>) -> Value {
        let mut defs = Map::new();
        while let Some(name) = refs.pop_first() {
            if defs.contains_key(&name) {
                continue;
            }
            let Some(schema) = self.root["$defs"].get(&name) else {
                continue;
            };
            collect_refs(schema, &mut refs);
            defs.insert(name, schema.clone());
        }
        Value::Object(defs)
    }

    /// Checks the body of the command `key` before it is sent: unknown fields and enum values
    /// (unless `allow_unknown`), types, formats, and every missing required field, in one error.
    pub fn check_body(
        &self,
        key: &str,
        body: &Value,
        fields: &[Field],
        allow_unknown: bool,
    ) -> Result<(), CliError> {
        let command = self.keys.get(key).and_then(|words| self.command(words));
        let Some(schema) = command.and_then(|c| c.get("body")) else {
            return Ok(());
        };
        let mut check = Check {
            schema: self,
            allow_unknown,
            errors: Vec::new(),
        };
        check.value(&schema["schema"], body, "", 0);
        if check.errors.is_empty() {
            return Ok(());
        }
        let errors = check
            .errors
            .into_iter()
            .map(|(path, message)| {
                let flag = flag_of(fields, &path);
                json!({"path": path, "flag": flag, "message": message})
            })
            .collect();
        Err(CliError::invalid_input("body", errors))
    }

    /// Checks the parameters of the command `key` against the keywords of their schemas
    /// (bounds, lengths, patterns, formats, list sizes), clap and serde having checked their
    /// types. `given` has the text of each argument given, by its id (`per-page`, `thing-id`).
    pub fn check_params(
        &self,
        key: &str,
        given: impl Fn(&str) -> Option<Vec<String>>,
    ) -> Result<(), CliError> {
        let command = self.keys.get(key).and_then(|words| self.command(words));
        let params = command.and_then(|c| c["params"].as_array());
        let mut errors = Vec::new();
        for param in params.into_iter().flatten() {
            let arg = param["arg"].as_str().unwrap_or_default();
            let schema = &param["schema"];
            let id = arg.trim_start_matches("--").trim_matches(['<', '>']);
            let id = id.to_lowercase().replace('_', "-");
            let Some(texts) = given(&id).filter(|_| schema["format"] != "binary") else {
                continue;
            };
            let value = match schema["type"] == "array" {
                true => Value::Array(texts.iter().map(|t| typed(&schema["items"], t)).collect()),
                false => texts.last().map_or(Value::Null, |text| typed(schema, text)),
            };
            let mut check = Check {
                schema: self,
                allow_unknown: true,
                errors: Vec::new(),
            };
            let name = param["name"].as_str().unwrap_or(arg);
            check.value(schema, &value, name, 0);
            errors.extend(
                check
                    .errors
                    .into_iter()
                    .map(|(path, message)| json!({"path": path, "flag": arg, "message": message})),
            );
        }
        match errors.is_empty() {
            true => Ok(()),
            false => Err(CliError::invalid_input("parameters", errors)),
        }
    }
}

/// The JSON value of an argument's text, as the type of `schema` reads it.
fn typed(schema: &Value, text: &str) -> Value {
    let number = || {
        serde_json::from_str::<Value>(text)
            .ok()
            .filter(Value::is_number)
    };
    match schema["type"].as_str() {
        Some("integer" | "number") => number().unwrap_or_else(|| text.into()),
        Some("boolean") => text
            .parse::<bool>()
            .map_or_else(|_| text.into(), Value::Bool),
        _ => text.into(),
    }
}

fn collect_refs(schema: &Value, refs: &mut BTreeSet<String>) {
    match schema {
        Value::Object(map) => {
            if let Some(reference) = map.get("$ref").and_then(Value::as_str) {
                refs.insert(reference.trim_start_matches("#/$defs/").to_owned());
            }
            map.values().for_each(|value| collect_refs(value, refs));
        }
        Value::Array(items) => items.iter().for_each(|item| collect_refs(item, refs)),
        _ => {}
    }
}

/// The flag setting `path` or the object holding it: `--billing-address` for
/// `billing_address.zip`.
fn flag_of(fields: &[Field], path: &str) -> Option<String> {
    fields
        .iter()
        .filter(|field| {
            let own = field.path();
            path == own
                || path.starts_with(&format!("{own}."))
                || path.starts_with(&format!("{own}["))
        })
        .max_by_key(|field| field.path().len())
        .map(|field| format!("--{}", field.flag))
}

struct Check<'s> {
    schema: &'s Schema,
    allow_unknown: bool,
    errors: Vec<(String, String)>,
}

/// Guards against schemas referring to themselves forever.
const MAX_DEPTH: usize = 64;

impl<'s> Check<'s> {
    /// Records an error once: a reference and its target may both have a keyword.
    fn error(&mut self, path: &str, message: impl Into<String>) {
        let error = (path.to_owned(), message.into());
        if !self.errors.contains(&error) {
            self.errors.push(error);
        }
    }

    fn value(&mut self, schema: &Value, value: &Value, path: &str, depth: usize) {
        if depth > MAX_DEPTH {
            return;
        }
        if let Some(reference) = schema.get("$ref").and_then(Value::as_str) {
            if value.is_null() && schema["nullable"] == true {
                return;
            }
            if let Some(target) = self.schema.def(reference) {
                self.value(target, value, path, depth + 1);
            }
            return self.keywords(schema, value, path);
        }
        if value.is_null() {
            if schema["nullable"] != true && !schema.as_object().is_none_or(Map::is_empty) {
                self.error(path, "must not be null");
            }
            return;
        }
        if let Some(variants) = schema.get("oneOf").and_then(Value::as_array) {
            return self.one_of(schema, variants, value, path, depth);
        }
        if let Some(values) = schema.get("enum").and_then(Value::as_array) {
            if !values.contains(value) && !self.allow_unknown {
                let message = unknown_value(value, values);
                self.error(path, message);
            }
            return;
        }
        let typed = match schema.get("type").and_then(Value::as_str) {
            Some("object") => {
                self.object(schema, value, path, &[], depth);
                return;
            }
            Some("array") => match value.as_array() {
                Some(items) => {
                    for (i, item) in items.iter().enumerate() {
                        self.value(&schema["items"], item, &format!("{path}[{i}]"), depth + 1);
                    }
                    true
                }
                None => self.expected(path, "an array", value),
            },
            Some("string") => self.string(schema, value, path),
            Some("integer") => self.integer(schema, value, path),
            Some("number") if !value.is_number() => self.expected(path, "a number", value),
            Some("boolean") if !value.is_boolean() => self.expected(path, "true or false", value),
            _ => true,
        };
        if typed {
            self.keywords(schema, value, path);
        }
    }

    /// Reports that `value` is not `what`; returns `false`, the value having no such type.
    fn expected(&mut self, path: &str, what: &str, value: &Value) -> bool {
        self.error(path, format!("expected {what}, got {}", kind(value)));
        false
    }

    /// The validation keywords of `schema` that apply to `value`: bounds, lengths, `pattern`,
    /// `format`, list sizes and unique items.
    fn keywords(&mut self, schema: &Value, value: &Value, path: &str) {
        let format = schema.get("format").and_then(Value::as_str);
        let number = match value {
            Value::String(text) if format == Some("decimal") => text.trim().parse().ok(),
            Value::String(_) => None,
            value => value.as_f64(),
        };
        if let Some(number) = number {
            for message in bounds(schema, value, number) {
                self.error(path, message);
            }
        }
        if let Some(text) = value.as_str() {
            for message in text_keywords(schema, text, format) {
                self.error(path, message);
            }
        }
        if let Some(items) = value.as_array() {
            for message in item_keywords(schema, items) {
                self.error(path, message);
            }
        }
    }

    fn one_of(
        &mut self,
        schema: &Value,
        variants: &[Value],
        value: &Value,
        path: &str,
        depth: usize,
    ) {
        if let Some(tag) = schema
            .pointer("/discriminator/propertyName")
            .and_then(Value::as_str)
        {
            let mapping = schema
                .pointer("/discriminator/mapping")
                .and_then(Value::as_object);
            let names: Vec<Value> = mapping
                .map(|mapping| mapping.keys().cloned().map(Value::String).collect())
                .unwrap_or_default();
            let Some(object) = value.as_object() else {
                return self.error(path, format!("expected an object, got {}", kind(value)));
            };
            let at = join(path, tag);
            let Some(given) = object.get(tag) else {
                return self.error(&at, format!("required ({})", one_of(&names)));
            };
            let tagged: Vec<&Value> = variants
                .iter()
                .map(|variant| self.resolve(variant))
                .filter(|variant| {
                    variant.pointer(&format!("/properties/{tag}/const")) == Some(given)
                })
                .collect();
            let mapped = given
                .as_str()
                .and_then(|given| mapping?.get(given))
                .and_then(Value::as_str)
                .and_then(|reference| self.schema.def(reference));
            if tagged.len() > 1 {
                let shared: Vec<Value> = tagged.into_iter().cloned().collect();
                return self.best_of(&shared, value, path, depth);
            }
            match tagged.first().copied().or(mapped) {
                Some(variant) => self.object(variant, value, path, &[tag], depth + 1),
                None if self.allow_unknown => {}
                None => self.error(&at, unknown_value(given, &names)),
            }
            return;
        }
        self.best_of(variants, value, path, depth);
    }

    /// Passes when `value` is one of `variants`, else reports the errors of the closest one.
    fn best_of(&mut self, variants: &[Value], value: &Value, path: &str, depth: usize) {
        let mut best: Option<Vec<(String, String)>> = None;
        for variant in variants {
            let mut check = Check {
                schema: self.schema,
                allow_unknown: self.allow_unknown,
                errors: Vec::new(),
            };
            check.value(variant, value, path, depth + 1);
            if check.errors.is_empty() {
                return;
            }
            if best
                .as_ref()
                .is_none_or(|best| check.errors.len() < best.len())
            {
                best = Some(check.errors);
            }
        }
        self.errors.extend(best.unwrap_or_default());
    }

    fn object(
        &mut self,
        schema: &Value,
        value: &Value,
        path: &str,
        allowed: &[&str],
        depth: usize,
    ) {
        let schema = self.resolve(schema);
        let Some(object) = value.as_object() else {
            return self.error(path, format!("expected an object, got {}", kind(value)));
        };
        let mut properties = Map::new();
        let mut required = Vec::new();
        let mut additional = None;
        self.gather(schema, &mut properties, &mut required, &mut additional, 0);
        for name in &required {
            if !object.contains_key(name) && !allowed.contains(&name.as_str()) {
                let message = match properties.get(name).map(|schema| self.describe(schema)) {
                    Some(what) if !what.is_empty() => format!("required ({what})"),
                    _ => "required".to_owned(),
                };
                self.error(&join(path, name), message);
            }
        }
        for (key, item) in object {
            let at = join(path, key);
            if item.is_null() && !required.contains(key) {
                continue;
            }
            match properties.get(key) {
                Some(property) => self.value(property, item, &at, depth + 1),
                None if allowed.contains(&key.as_str()) => {}
                None => match &additional {
                    Some(Value::Bool(false)) if !self.allow_unknown => {
                        let known: Vec<&str> = properties.keys().map(String::as_str).collect();
                        self.error(&at, unknown_field(key, &known));
                    }
                    Some(additional @ Value::Object(_)) => {
                        self.value(additional, item, &at, depth + 1);
                    }
                    _ => {}
                },
            }
        }
    }

    fn resolve<'v>(&self, schema: &'v Value) -> &'v Value
    where
        's: 'v,
    {
        match schema.get("$ref").and_then(Value::as_str) {
            Some(reference) => self.schema.def(reference).unwrap_or(schema),
            None => schema,
        }
    }

    /// The properties, required names and additional properties of an object schema,
    /// with those of the objects it flattens (`allOf`).
    fn gather(
        &self,
        schema: &Value,
        properties: &mut Map<String, Value>,
        required: &mut Vec<String>,
        additional: &mut Option<Value>,
        depth: usize,
    ) {
        if depth > MAX_DEPTH {
            return;
        }
        let schema = self.resolve(schema);
        for (name, property) in schema["properties"].as_object().into_iter().flatten() {
            properties.insert(name.clone(), property.clone());
        }
        let names = schema["required"].as_array().into_iter().flatten();
        required.extend(names.filter_map(Value::as_str).map(str::to_owned));
        if let Some(value) = schema.get("additionalProperties") {
            if additional.is_none() || value != &Value::Bool(false) {
                *additional = Some(value.clone());
            }
        }
        for part in schema["allOf"].as_array().into_iter().flatten() {
            self.gather(part, properties, required, additional, depth + 1);
        }
    }

    /// A short description of what a schema takes, for "required" errors.
    fn describe(&self, schema: &Value) -> String {
        let schema = self.resolve(schema);
        if let Some(values) = schema.get("enum").and_then(Value::as_array) {
            return one_of(values);
        }
        if let Some(tag) = schema.pointer("/discriminator/propertyName") {
            let names = schema
                .pointer("/discriminator/mapping")
                .and_then(Value::as_object);
            let names: Vec<Value> = names
                .map(|names| names.keys().cloned().map(Value::String).collect())
                .unwrap_or_default();
            return format!("an object whose {tag} is {}", one_of(&names));
        }
        let format = schema.get("format").and_then(Value::as_str);
        match (schema.get("type").and_then(Value::as_str), format) {
            (Some("string"), Some(format)) => hint(format).unwrap_or("a string").to_owned(),
            (Some("string"), None) => "a string".to_owned(),
            (Some("integer"), _) => "an integer".to_owned(),
            (Some("number"), _) => "a number".to_owned(),
            (Some("boolean"), _) => "true or false".to_owned(),
            (Some("array"), _) => "an array".to_owned(),
            (Some("object"), _) => "an object".to_owned(),
            _ => String::new(),
        }
    }

    fn string(&mut self, schema: &Value, value: &Value, path: &str) -> bool {
        let format = schema.get("format").and_then(Value::as_str);
        match value {
            Value::String(_) => true,
            Value::Number(_) if format == Some("decimal") => true,
            value => self.expected(path, "a string", value),
        }
    }

    /// Checks the range of the integer's `format` (`int32`), its bounds being keywords.
    fn integer(&mut self, schema: &Value, value: &Value, path: &str) -> bool {
        let Some(number) = value
            .as_i64()
            .map(i128::from)
            .or(value.as_u64().map(i128::from))
        else {
            return self.expected(path, "an integer", value);
        };
        let format = schema.get("format").and_then(Value::as_str);
        let (min, max) = match format {
            Some("int16") => (i128::from(i16::MIN), i128::from(i16::MAX)),
            Some("uint16") => (0, i128::from(u16::MAX)),
            Some("int32") => (i128::from(i32::MIN), i128::from(i32::MAX)),
            Some("uint64") => (0, i128::from(u64::MAX)),
            _ => (i128::from(i64::MIN), i128::from(i64::MAX)),
        };
        if number < min || number > max {
            self.error(path, format!("{number} is out of range: {min} to {max}"));
            return false;
        }
        true
    }
}

/// What the numeric keywords of `schema` say of `number`, `value` as given.
fn bounds(schema: &Value, value: &Value, number: f64) -> Vec<String> {
    let keyword = |key: &str| schema.get(key).filter(|bound| bound.is_number());
    let mut messages = Vec::new();
    let mut check = |key: &str, words: &str, fails: fn(f64, f64) -> bool| {
        if let Some(bound) = keyword(key) {
            if fails(number, bound.as_f64().unwrap_or_default()) {
                messages.push(format!("must be {words} {bound}"));
            }
        }
    };
    check("minimum", "at least", |n, bound| n < bound);
    check("maximum", "at most", |n, bound| n > bound);
    check("exclusiveMinimum", "greater than", |n, bound| n <= bound);
    check("exclusiveMaximum", "less than", |n, bound| n >= bound);
    if let Some(step) = keyword("multipleOf") {
        if !is_multiple(value, number, step) {
            messages.push(format!("must be a multiple of {step}"));
        }
    }
    messages
}

/// Whether `number` is a multiple of `step`: exactly for integers, else within a rounding error.
fn is_multiple(value: &Value, number: f64, step: &Value) -> bool {
    if let (Some(value), Some(step)) = (value.as_i64(), step.as_i64()) {
        return step == 0 || value % step == 0;
    }
    let step = step.as_f64().unwrap_or_default();
    if step <= 0.0 {
        return true;
    }
    let quotient = number / step;
    (quotient - quotient.round()).abs() < 1e-9 * quotient.abs().max(1.0)
}

/// What the string keywords of `schema` say of `text`: lengths, `pattern`, `format`.
fn text_keywords(schema: &Value, text: &str, format: Option<&str>) -> Vec<String> {
    let mut messages = Vec::new();
    let length = text.chars().count() as u64;
    let plural = |n: u64| if n == 1 { "" } else { "s" };
    if let Some(min) = schema.get("minLength").and_then(Value::as_u64) {
        if length < min {
            messages.push(format!(
                "must be at least {min} character{} long",
                plural(min)
            ));
        }
    }
    if let Some(max) = schema.get("maxLength").and_then(Value::as_u64) {
        if length > max {
            messages.push(format!(
                "must be at most {max} character{} long",
                plural(max)
            ));
        }
    }
    if let Some(pattern) = schema.get("pattern").and_then(Value::as_str) {
        // Patterns the regex engine does not support are left to the API.
        let regex = regex_bites::Regex::new(pattern);
        if regex.is_ok_and(|regex| !regex.is_match(text)) {
            messages.push(format!("must match the pattern {pattern}"));
        }
    }
    if let Some(format) = format {
        if !is_format(format, text) {
            let expected = hint(format).unwrap_or("a string");
            messages.push(format!("invalid value `{text}`: expected {expected}"));
        }
    }
    messages
}

/// What the list keywords of `schema` say of `items`: sizes and unique items.
fn item_keywords(schema: &Value, items: &[Value]) -> Vec<String> {
    let mut messages = Vec::new();
    let count = items.len() as u64;
    let plural = |n: u64| if n == 1 { "" } else { "s" };
    if let Some(min) = schema.get("minItems").and_then(Value::as_u64) {
        if count < min {
            messages.push(format!("must have at least {min} item{}", plural(min)));
        }
    }
    if let Some(max) = schema.get("maxItems").and_then(Value::as_u64) {
        if count > max {
            messages.push(format!("must have at most {max} item{}", plural(max)));
        }
    }
    if schema["uniqueItems"] == true {
        let repeated = items
            .iter()
            .enumerate()
            .find(|(i, item)| items[..*i].contains(item));
        if let Some((_, item)) = repeated {
            messages.push(format!("must not repeat {}", text(item)));
        }
    }
    messages
}

/// Whether `text` is valid in the string `format`; unknown formats are.
fn is_format(format: &str, text: &str) -> bool {
    match format {
        "date" => is_date(text),
        "date-time" => is_date_time(text),
        "uuid" => is_uuid(text),
        "decimal" => text.trim().parse::<f64>().is_ok(),
        "email" => is_email(text),
        "uri" | "url" => is_uri(text),
        "hostname" => is_hostname(text),
        "ipv4" => text.parse::<std::net::Ipv4Addr>().is_ok(),
        "ipv6" => text.parse::<std::net::Ipv6Addr>().is_ok(),
        _ => true,
    }
}

/// The hint of a string format, for errors and help.
pub fn hint(format: &str) -> Option<&'static str> {
    match format {
        "date" => Some("a date, YYYY-MM-DD"),
        "date-time" => Some("a date-time, YYYY-MM-DDTHH:MM:SSZ (RFC 3339)"),
        "uuid" => Some("a UUID"),
        "decimal" => Some("a decimal number, as a string"),
        "email" => Some("an email address"),
        "uri" | "url" => Some("an absolute URI, such as https://example.com"),
        "hostname" => Some("a hostname, such as example.com"),
        "ipv4" => Some("an IPv4 address"),
        "ipv6" => Some("an IPv6 address"),
        _ => None,
    }
}

fn join(path: &str, key: &str) -> String {
    match path {
        "" => key.to_owned(),
        path => format!("{path}.{key}"),
    }
}

fn kind(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "a boolean",
        Value::Number(_) => "a number",
        Value::String(_) => "a string",
        Value::Array(_) => "an array",
        Value::Object(_) => "an object",
    }
}

fn one_of(values: &[Value]) -> String {
    let shown: Vec<String> = values
        .iter()
        .take(SHOWN_VALUES)
        .map(|value| match value {
            Value::String(text) => text.clone(),
            other => other.to_string(),
        })
        .collect();
    let more = match values.len().saturating_sub(SHOWN_VALUES) {
        0 => String::new(),
        more => format!(", … ({more} more)"),
    };
    format!("one of {}{more}", shown.join(", "))
}

/// A value as errors quote it: strings without their quotes.
fn text(value: &Value) -> String {
    match value {
        Value::String(text) => format!("`{text}`"),
        other => format!("`{other}`"),
    }
}

fn unknown_value(value: &Value, values: &[Value]) -> String {
    let text = match value {
        Value::String(text) => text.clone(),
        other => other.to_string(),
    };
    let names: Vec<&str> = values.iter().filter_map(Value::as_str).collect();
    let suggestion = match suggest(&text, &names) {
        Some(name) => format!("did you mean {name}? "),
        None => String::new(),
    };
    format!(
        "unknown value `{text}`; {suggestion}expected {}",
        one_of(values)
    )
}

fn unknown_field(key: &str, known: &[&str]) -> String {
    match suggest(key, known) {
        Some(name) => format!("unknown field; did you mean {name}?"),
        None if known.is_empty() => "unknown field: this object takes none".to_owned(),
        None => format!(
            "unknown field; expected {}",
            one_of(&known.iter().map(|k| Value::from(*k)).collect::<Vec<_>>())
        ),
    }
}

/// The candidate `given` most likely meant: the same but for case and separators, a close
/// spelling, or the only one sharing a word with it (`postal_code`, `zip_code`).
pub fn suggest<'c>(given: &str, candidates: &[&'c str]) -> Option<&'c str> {
    let normal = |text: &str| -> String {
        text.chars()
            .filter(|c| c.is_alphanumeric())
            .flat_map(char::to_lowercase)
            .collect()
    };
    if let Some(same) = candidates.iter().find(|c| normal(c) == normal(given)) {
        return Some(same);
    }
    let close = candidates
        .iter()
        .map(|candidate| (distance(&normal(given), &normal(candidate)), *candidate))
        .min_by_key(|(distance, _)| *distance)
        .filter(|(distance, candidate)| *distance <= (given.len().min(candidate.len()) / 3).max(1));
    if let Some((_, candidate)) = close {
        return Some(candidate);
    }
    let words = |text: &str| -> BTreeSet<String> {
        text.split(|c: char| !c.is_alphanumeric())
            .filter(|word| word.len() > 1)
            .map(str::to_lowercase)
            .collect()
    };
    let given = words(given);
    let mut sharing = candidates
        .iter()
        .filter(|candidate| !words(candidate).is_disjoint(&given));
    match (sharing.next(), sharing.next()) {
        (Some(only), None) => Some(only),
        _ => None,
    }
}

/// Edits from `a` to `b`, a swap of neighbors counting as one.
fn distance(a: &str, b: &str) -> usize {
    let (a, b): (Vec<char>, Vec<char>) = (a.chars().collect(), b.chars().collect());
    let mut d = vec![vec![0; b.len() + 1]; a.len() + 1];
    for (i, row) in d.iter_mut().enumerate() {
        row[0] = i;
    }
    for (j, cell) in d[0].iter_mut().enumerate() {
        *cell = j;
    }
    for i in 1..=a.len() {
        for j in 1..=b.len() {
            let cost = usize::from(a[i - 1] != b[j - 1]);
            d[i][j] = (d[i - 1][j] + 1)
                .min(d[i][j - 1] + 1)
                .min(d[i - 1][j - 1] + cost);
            if i > 1 && j > 1 && a[i - 1] == b[j - 2] && a[i - 2] == b[j - 1] {
                d[i][j] = d[i][j].min(d[i - 2][j - 2] + 1);
            }
        }
    }
    d[a.len()][b.len()]
}

fn digits(text: &str) -> Option<u32> {
    match text.bytes().all(|b| b.is_ascii_digit()) && !text.is_empty() {
        true => text.parse().ok(),
        false => None,
    }
}

fn is_date(text: &str) -> bool {
    let mut parts = text.split('-');
    let (Some(year), Some(month), Some(day), None) =
        (parts.next(), parts.next(), parts.next(), parts.next())
    else {
        return false;
    };
    year.len() == 4
        && digits(year).is_some()
        && month.len() == 2
        && digits(month).is_some_and(|m| (1..=12).contains(&m))
        && day.len() == 2
        && digits(day).is_some_and(|d| (1..=31).contains(&d))
}

fn is_date_time(text: &str) -> bool {
    let Some((date, time)) = text.split_once(['T', 't', ' ']) else {
        return false;
    };
    let zone = time.find(['Z', 'z', '+', '-']).map_or("", |at| &time[at..]);
    let clock = &time[..time.len() - zone.len()];
    let clock = clock.split_once('.').map_or(clock, |(clock, _)| clock);
    let mut fields = clock.split(':');
    let valid_clock = (0..3).all(|i| {
        fields.next().is_some_and(|field| {
            field.len() == 2 && digits(field).is_some_and(|n| n < 60 + 4 * u32::from(i == 0))
        })
    }) && fields.next().is_none();
    let valid_zone = matches!(zone, "Z" | "z")
        || (zone.len() == 6
            && zone[1..]
                .split_once(':')
                .is_some_and(|(h, m)| digits(h).is_some() && digits(m).is_some()));
    is_date(date) && valid_clock && valid_zone
}

fn is_email(text: &str) -> bool {
    let Some((local, domain)) = text.rsplit_once('@') else {
        return false;
    };
    !local.is_empty() && !text.contains(char::is_whitespace) && domain.contains('.') && {
        is_hostname(domain) || (domain.starts_with('[') && domain.ends_with(']'))
    }
}

/// An absolute URI: a scheme, then no whitespace.
fn is_uri(text: &str) -> bool {
    let Some((scheme, rest)) = text.split_once(':') else {
        return false;
    };
    let mut chars = scheme.chars();
    chars.next().is_some_and(|c| c.is_ascii_alphabetic())
        && chars.all(|c| c.is_ascii_alphanumeric() || "+-.".contains(c))
        && !rest.is_empty()
        && !text.contains(|c: char| c.is_whitespace() || c.is_control())
}

fn is_hostname(text: &str) -> bool {
    let text = text.strip_suffix('.').unwrap_or(text);
    !text.is_empty()
        && text.len() <= 253
        && text.split('.').all(|label| {
            (1..=63).contains(&label.len())
                && !label.starts_with('-')
                && !label.ends_with('-')
                && label
                    .bytes()
                    .all(|b| b.is_ascii_alphanumeric() || b == b'-')
        })
}

fn is_uuid(text: &str) -> bool {
    let groups: Vec<&str> = text.split('-').collect();
    groups.iter().map(|g| g.len()).eq([8, 4, 4, 4, 12])
        && groups
            .iter()
            .all(|g| g.bytes().all(|b| b.is_ascii_hexdigit()))
}

#[cfg(test)]
mod tests {
    use super::super::body::Kind;
    use super::*;

    fn schema() -> Schema {
        let parts = json!({
            "resources": {"customers": "customers", "plans": "plans"},
            "commands": {
                "customers.create": {
                    "resource": "customers", "command": "create",
                    "method": "POST", "path": "/customers", "summary": "Create a customer",
                    "params": [{"name": "idempotency_key", "in": "header", "arg": "--idempotency-key",
                                "required": false, "schema": {"type": "string"}}],
                    "body": {"content": "json", "required": true, "schema": {"$ref": "#/$defs/CustomerCreate"}},
                    "response": {"$ref": "#/$defs/Customer"},
                },
                "customers.list": {"resource": "customers", "command": "list",
                                   "method": "GET", "path": "/customers", "summary": "List"},
            },
        });
        let more = json!({
            "commands": {
                "plans.create": {"resource": "plans", "command": "create",
                                 "method": "POST", "path": "/plans", "summary": "Create a plan"},
            },
            "$defs": {
                "CustomerCreate": {
                    "type": "object", "additionalProperties": false,
                    "required": ["name", "currency", "billing_address"],
                    "properties": {
                        "name": {"type": "string"},
                        "currency": {"$ref": "#/$defs/Currency"},
                        "billing_address": {"$ref": "#/$defs/Address"},
                        "since": {"type": "string", "format": "date"},
                        "net_terms": {"type": "integer", "format": "int32", "minimum": 0},
                        "payment": {"$ref": "#/$defs/Payment"},
                        "tags": {"type": "array", "items": {"type": "string"}},
                        "metadata": {"type": "object", "additionalProperties": {"type": "string"}},
                        "parent": {"$ref": "#/$defs/CustomerCreate", "nullable": true},
                    },
                },
                "Currency": {"type": "string", "enum": ["EUR", "USD"]},
                "Address": {
                    "type": "object", "additionalProperties": false, "required": ["line1"],
                    "properties": {"line1": {"type": "string"}, "city": {"type": "string"},
                                   "zip_code": {"type": "string"}},
                },
                "Payment": {
                    "oneOf": [{"$ref": "#/$defs/Online"}, {"$ref": "#/$defs/Bank"}],
                    "discriminator": {"propertyName": "type", "mapping": {
                        "online": "#/$defs/Online", "bank_transfer": "#/$defs/Bank"}},
                },
                "Online": {"type": "object", "additionalProperties": false, "properties": {}},
                "Bank": {"type": "object", "additionalProperties": false, "required": ["iban"],
                         "properties": {"iban": {"type": "string"}}},
                "Customer": {"type": "object", "properties": {"id": {"type": "string"}}},
            },
        });
        Schema::parse(&[&parts.to_string(), &more.to_string()]).unwrap()
    }

    const FIELDS: &[Field] = &[
        Field::new("billing-address", "billing_address", Kind::Json),
        Field::new("name", "name", Kind::String),
    ];

    fn errors(body: Value) -> Vec<Value> {
        let error = schema()
            .check_body("customers.create", &body, FIELDS, false)
            .unwrap_err();
        error.errors().unwrap().to_vec()
    }

    fn valid() -> Value {
        json!({"name": "Acme", "currency": "EUR", "billing_address": {"line1": "1 Main St"}})
    }

    #[test]
    fn valid_bodies_pass() {
        let mut body = valid();
        body["payment"] = json!({"type": "bank_transfer", "iban": "DE00"});
        body["since"] = json!("2026-01-31");
        body["metadata"] = json!({"a": "b"});
        body["parent"] = Value::Null;
        schema()
            .check_body("customers.create", &body, FIELDS, false)
            .unwrap();
        schema()
            .check_body("customers.list", &json!({}), &[], false)
            .unwrap();
    }

    #[test]
    fn unknown_fields_are_rejected_with_a_suggestion() {
        let mut body = valid();
        body["billing_address"]["postal_code"] = json!("10115");
        let error = schema()
            .check_body("customers.create", &body, FIELDS, false)
            .unwrap_err();
        assert_eq!(
            error.message(),
            "invalid body: billing_address.postal_code (--billing-address): unknown field; did you mean zip_code?"
        );
        assert_eq!(
            error.errors().unwrap()[0]["flag"],
            json!("--billing-address")
        );
        body["nmae"] = json!("x");
        assert_eq!(
            errors(body.clone())[1]["message"],
            json!("unknown field; did you mean name?")
        );
        schema()
            .check_body("customers.create", &body, FIELDS, true)
            .unwrap();
    }

    #[test]
    fn every_missing_field_is_reported_at_once() {
        let found = errors(json!({}));
        let paths: Vec<&str> = found.iter().map(|e| e["path"].as_str().unwrap()).collect();
        assert_eq!(paths, ["name", "currency", "billing_address"]);
        assert_eq!(found[1]["message"], json!("required (one of EUR, USD)"));
        assert_eq!(found[0]["flag"], json!("--name"));
    }

    #[test]
    fn unknown_enum_and_discriminator_values_list_the_valid_ones() {
        let mut body = valid();
        body["currency"] = json!("eur");
        body["payment"] = json!({"type": "bank"});
        let found = errors(body);
        assert_eq!(
            found[0]["message"],
            json!("unknown value `eur`; did you mean EUR? expected one of EUR, USD")
        );
        assert_eq!(found[1]["path"], json!("payment.type"));
        assert_eq!(
            found[1]["message"],
            json!("unknown value `bank`; did you mean bank_transfer? expected one of online, bank_transfer")
        );
        let mut missing = valid();
        missing["payment"] = json!({"type": "bank_transfer"});
        assert_eq!(errors(missing)[0]["path"], json!("payment.iban"));
    }

    #[test]
    fn variants_are_picked_by_their_tag_even_when_they_share_it() {
        let part = json!({
            "commands": {"items.create": {"resource": "items", "command": "create", "method": "POST",
                "path": "/items", "body": {"content": "json", "required": true,
                "schema": {"$ref": "#/$defs/Item"}}}},
            "resources": {"items": "items"},
            "$defs": {
                "Item": {"oneOf": [{"$ref": "#/$defs/Item.message.1"}, {"$ref": "#/$defs/Item.message.2"},
                                   {"$ref": "#/$defs/Item.call"}],
                         "discriminator": {"propertyName": "type", "mapping": {
                             "message": "#/$defs/Item.message.1", "call": "#/$defs/Item.call"}}},
                "Item.message.1": {"type": "object", "additionalProperties": false, "required": ["type", "text"],
                    "properties": {"type": {"type": "string", "const": "message"}, "text": {"type": "string"}}},
                "Item.message.2": {"type": "object", "additionalProperties": false, "required": ["type", "parts"],
                    "properties": {"type": {"type": "string", "const": "message"},
                                   "parts": {"type": "array", "items": {"type": "string"}}}},
                "Item.call": {"type": "object", "additionalProperties": false, "required": ["type", "name"],
                    "properties": {"type": {"type": "string", "const": "call"}, "name": {"type": "string"}}},
            },
        });
        let schema = Schema::parse(&[&part.to_string()]).unwrap();
        let check = |body: Value| schema.check_body("items.create", &body, &[], false);
        assert!(check(json!({"type": "message", "text": "hi"})).is_ok());
        assert!(check(json!({"type": "message", "parts": ["hi"]})).is_ok());
        assert!(check(json!({"type": "call", "name": "f"})).is_ok());
        let error = check(json!({"type": "message", "parts": "hi"})).unwrap_err();
        assert_eq!(error.errors().unwrap()[0]["path"], "parts");
        let error = check(json!({"type": "call", "text": "hi"})).unwrap_err();
        let paths: Vec<&Value> = error.errors().unwrap().iter().map(|e| &e["path"]).collect();
        assert_eq!(paths, ["name", "text"]);
    }

    #[test]
    fn types_formats_and_ranges_are_checked() {
        let mut body = valid();
        body["since"] = json!("31/01/2026");
        body["net_terms"] = json!(-1);
        body["tags"] = json!(["a", 1]);
        body["name"] = Value::Null;
        let messages: Vec<String> = errors(body)
            .iter()
            .map(|e| {
                format!(
                    "{}: {}",
                    e["path"].as_str().unwrap(),
                    e["message"].as_str().unwrap()
                )
            })
            .collect();
        assert_eq!(
            messages,
            [
                "name: must not be null",
                "since: invalid value `31/01/2026`: expected a date, YYYY-MM-DD",
                "net_terms: must be at least 0",
                "tags[1]: expected a string, got a number",
            ]
        );
    }

    #[test]
    fn integers_stay_in_the_range_of_their_format() {
        let mut body = valid();
        body["net_terms"] = json!(3_000_000_000_i64);
        assert_eq!(
            errors(body)[0]["message"],
            json!("3000000000 is out of range: -2147483648 to 2147483647")
        );
    }

    fn keyword_errors(schema: Value, value: Value) -> Vec<String> {
        let parts = json!({"$defs": {"Sku": {"type": "string", "pattern": "^[A-Z]{3}-[0-9]+$"}}});
        let root = Schema::parse(&[&parts.to_string()]).unwrap();
        let mut check = Check {
            schema: &root,
            allow_unknown: false,
            errors: Vec::new(),
        };
        check.value(&schema, &value, "x", 0);
        check
            .errors
            .into_iter()
            .map(|(_, message)| message)
            .collect()
    }

    #[test]
    fn keywords_bound_numbers_texts_and_lists() {
        let page = json!({"type": "integer", "minimum": 1, "maximum": 100});
        assert_eq!(
            keyword_errors(page.clone(), json!(101)),
            ["must be at most 100"]
        );
        assert_eq!(
            keyword_errors(page.clone(), json!(0)),
            ["must be at least 1"]
        );
        assert!(keyword_errors(page, json!(100)).is_empty());
        let price = json!({"type": "number", "exclusiveMinimum": 0, "multipleOf": 0.01});
        assert_eq!(
            keyword_errors(price.clone(), json!(0)),
            ["must be greater than 0"]
        );
        assert_eq!(
            keyword_errors(price.clone(), json!(1.005)),
            ["must be a multiple of 0.01"]
        );
        assert!(keyword_errors(price, json!(19.99)).is_empty());
        let decimal = json!({"type": "string", "format": "decimal", "maximum": 10});
        assert_eq!(
            keyword_errors(decimal, json!("10.5")),
            ["must be at most 10"]
        );
        let name = json!({"type": "string", "minLength": 2, "maxLength": 3});
        assert_eq!(
            keyword_errors(name.clone(), json!("a")),
            ["must be at least 2 characters long"]
        );
        assert_eq!(
            keyword_errors(name, json!("éèêë")),
            ["must be at most 3 characters long"]
        );
        let tags = json!({"type": "array", "maxItems": 2, "uniqueItems": true,
                          "items": {"type": "string", "minLength": 1}});
        assert_eq!(
            keyword_errors(tags, json!(["a", "", "a"])),
            [
                "must be at least 1 character long",
                "must have at most 2 items",
                "must not repeat `a`"
            ]
        );
    }

    #[test]
    fn references_keep_their_own_keywords_and_patterns_unsupported_pass() {
        let sku = json!({"$ref": "#/$defs/Sku", "maxLength": 5});
        assert_eq!(
            keyword_errors(sku, json!("abc-123")),
            [
                "must match the pattern ^[A-Z]{3}-[0-9]+$",
                "must be at most 5 characters long"
            ]
        );
        let lookahead = json!({"type": "string", "pattern": "^(?=a)"});
        assert!(keyword_errors(lookahead, json!("b")).is_empty());
    }

    #[test]
    fn string_formats() {
        let email = json!({"type": "string", "format": "email"});
        assert_eq!(
            keyword_errors(email.clone(), json!("jane@")),
            ["invalid value `jane@`: expected an email address"]
        );
        assert!(keyword_errors(email, json!("jane@acme.dev")).is_empty());
        let valid = [
            ("uri", "https://acme.dev/a?b=c"),
            ("uri", "urn:isbn:0451450523"),
            ("hostname", "api.acme.dev"),
            ("ipv4", "10.0.0.1"),
            ("ipv6", "::1"),
            ("password", "anything goes"),
        ];
        for (format, text) in valid {
            assert!(is_format(format, text), "{format}: {text}");
        }
        let invalid = [
            ("uri", "/relative"),
            ("uri", "https://a b"),
            ("hostname", "-acme.dev"),
            ("hostname", "a..b"),
            ("ipv4", "10.0.0.256"),
            ("ipv6", "10.0.0.1"),
            ("email", "a b@acme.dev"),
        ];
        for (format, text) in invalid {
            assert!(!is_format(format, text), "{format}: {text}");
        }
    }

    #[test]
    fn parameters_are_checked_by_their_argument() {
        let parts = json!({
            "resources": {"things": "things"},
            "commands": {"things.list": {
                "resource": "things", "command": "list", "method": "GET", "path": "/things",
                "params": [
                    {"name": "per_page", "in": "query", "arg": "--per-page", "required": false,
                     "schema": {"type": "integer", "minimum": 1, "maximum": 100}},
                    {"name": "thing_id", "in": "path", "arg": "<THING_ID>", "required": true,
                     "schema": {"type": "string", "pattern": "^th_"}},
                    {"name": "ids", "in": "query", "arg": "--ids", "required": false,
                     "schema": {"type": "array", "maxItems": 1, "items": {"type": "integer", "minimum": 0}}},
                ],
            }},
        });
        let schema = Schema::parse(&[&parts.to_string()]).unwrap();
        let given = |id: &str| match id {
            "per-page" => Some(vec!["500".to_owned()]),
            "thing-id" => Some(vec!["at_1".to_owned()]),
            "ids" => Some(vec!["1".to_owned(), "-1".to_owned()]),
            _ => None,
        };
        let error = schema.check_params("things.list", given).unwrap_err();
        assert_eq!(
            error.message(),
            "invalid parameters: per_page (--per-page): must be at most 100; \
             thing_id (<THING_ID>): must match the pattern ^th_; \
             ids[1] (--ids): must be at least 0; ids (--ids): must have at most 1 item"
        );
        schema.check_params("things.list", |_| None).unwrap();
    }

    #[test]
    fn formats() {
        assert!(is_date("2026-01-31") && !is_date("2026-1-31") && !is_date("2026-13-01"));
        assert!(
            is_date_time("2026-01-31T10:30:00Z") && is_date_time("2026-01-31T10:30:00.5+02:00")
        );
        assert!(!is_date_time("2026-01-31") && !is_date_time("2026-01-31T10:30Z"));
        assert!(is_uuid("123e4567-e89b-12d3-a456-426614174000") && !is_uuid("123"));
    }

    #[test]
    fn suggestions() {
        assert_eq!(
            suggest("postal_code", &["line1", "zip_code"]),
            Some("zip_code")
        );
        assert_eq!(suggest("zipCode", &["zip_code"]), Some("zip_code"));
        assert_eq!(suggest("curency", &["currency", "name"]), Some("currency"));
        assert_eq!(suggest("x", &["currency", "name"]), None);
        assert_eq!(suggest("billing_code", &["zip_code", "tax_code"]), None);
        assert_eq!(suggest("nmae", &["name"]), Some("name"));
    }

    #[test]
    fn the_index_lists_commands_under_a_prefix() {
        let all = schema().index(&[]);
        assert_eq!(all.len(), 3);
        let customers = schema().index(&["customers".to_owned()]);
        assert_eq!(
            customers[0],
            json!({"command": "customers create", "method": "POST",
                                        "path": "/customers", "summary": "Create a customer"})
        );
        assert_eq!(customers.len(), 2);
    }

    #[test]
    fn descriptions_inline_references_but_not_cycles() {
        let described = schema().describe("customers create", false).unwrap();
        let body = &described["body"];
        assert_eq!(
            body["properties"]["currency"]["enum"],
            json!(["EUR", "USD"])
        );
        assert_eq!(
            body["properties"]["billing_address"]["required"],
            json!(["line1"])
        );
        assert_eq!(
            body["properties"]["parent"]["$ref"],
            json!("#/$defs/CustomerCreate")
        );
        assert!(described["$defs"]["CustomerCreate"].is_object());
        assert_eq!(
            described["parameters"]["properties"]["--idempotency-key"]["in"],
            json!("header")
        );
        let response = schema().describe("customers create", true).unwrap();
        assert_eq!(
            response["response"]["properties"]["id"],
            json!({"type": "string"})
        );
        assert!(schema().describe("nope", false).is_none());
    }
}
